package com.example.order; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/orders") public class OrderController { @PostMapping public Map<String,String> create(){return Map.of("orderId",UUID.randomUUID().toString(),"status","PENDING");} @PostMapping("/{id}/complete") public Map<String,String> complete(@PathVariable String id){return Map.of("orderId",id,"status","COMPLETED");} @PostMapping("/{id}/cancel") public Map<String,String> cancel(@PathVariable String id){return Map.of("orderId",id,"status","CANCELLED");} }
